import ast, os, sys, collections
root=sys.argv[1]; classes=collections.defaultdict(list)
for dp,dn,fn in os.walk(root):
    dn[:]=[d for d in dn if d not in('.git','node_modules','graphify-out')]
    for f in fn:
        if not f.endswith('.py'): continue
        p=os.path.join(dp,f)
        try: t=ast.parse(open(p,encoding='utf-8').read())
        except Exception as e: print("ERR",p,e,file=sys.stderr); continue
        for n in ast.walk(t):
            if isinstance(n,ast.ClassDef):
                bases=[]
                for b in n.bases:
                    s=ast.unparse(b); bases.append(s.split('.')[-1].split('[')[0])
                classes[n.name].append((os.path.relpath(p,root),n.lineno,bases))
targets={'StockController'}; out=[]; changed=True; seen=set()
while changed:
    changed=False
    for name,defs in classes.items():
        for (p,l,b) in defs:
            if (p,l) in seen: continue
            if set(b)&targets:
                seen.add((p,l)); out.append((name,p,l,b)); targets.add(name); changed=True
for o in sorted(out,key=lambda x:x[1]):
    test='TEST' if ('/test' in '/'+o[1] or os.path.basename(o[1]).startswith('test_')) else ''
    print(test, o[0], f"{o[1]}:{o[2]}", o[3])
EOF
